 * @example
 * app.get("/sse", (event) => {
 *   const interval = setInterval(() => {}, 1000);
 *   onDispose(event, () => clearInterval(interval));
 *   // ... return a streaming response
 * });
 */
export function onDispose(event: H3Event, cb: DisposeCallback): void {
  _onDispose(event, cb);
